bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
docker inspect "$cid" --format 'state={{.State.Status}} restarts={{.RestartCount}} image={{.Image}} tag={{.Config.Image}}'
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import pg from 'pg';
import {readFileSync} from 'node:fs';
const p=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
const c=await p.connect();
try {
 await c.query('BEGIN READ ONLY');
 const q=async(label,sql,params=[])=>{const r=await c.query(sql,params);console.log(label+' '+JSON.stringify(r.rows));};
 console.log('TERMS_CONFIGURED='+Boolean(process.env.CREATEVDOBOT_TERMS_URL));console.log('INVOICE_MODE='+ (process.env.VIDEO_SALE_MODE==='invoice'));
 await q('DATABASE_STATUS', "SELECT current_database() AS db, (SELECT count(*) FROM videobot_listings) AS listings,(SELECT count(*) FROM videobot_creator_sessions) AS sessions,(SELECT count(*) FROM videobot_owner_update_jobs) AS jobs,(SELECT count(*) FROM videobot_webhook_updates) AS updates");
 await q('RECENT_LISTINGS',`SELECT left(md5(l.seller_user_id::text),10) AS owner_ref,left(md5(l.listing_id),10) AS ref,l.status,l.revision,l.created_at,l.updated_at,l.second_thumbnail_file_id IS NOT NULL AS two_thumbnails,l.sample_duration_seconds,l.fee_terms_accepted_at IS NOT NULL AS terms_accepted,(SELECT count(*) FROM videobot_post_receipts r WHERE r.listing_id=l.listing_id) AS receipts,(SELECT count(*) FROM videobot_post_receipts r WHERE r.listing_id=l.listing_id AND r.status='sent') AS sent_receipts FROM videobot_listings l ORDER BY created_at DESC LIMIT 20`);
 await q('RECENT_SESSIONS',`SELECT left(md5(owner_user_id::text),10) AS owner_ref,revision,state->>'screen' AS screen,state->>'publishing' AS publishing,state->'pendingVideoDraft'->>'revision' AS pending_revision,left(md5(state->'pendingVideoDraft'->>'listingId'),10) AS pending_ref,state->'draft'->>'mode' AS draft_mode,updated_at FROM videobot_creator_sessions ORDER BY updated_at DESC LIMIT 12`);
 await q('RECENT_RECEIPTS',`SELECT left(md5(r.listing_id),10) AS ref,r.revision,r.status,r.sale_mode,cardinality(r.free_message_ids) AS free_count,r.paid_message_id IS NOT NULL AS offer_recorded FROM videobot_post_receipts r JOIN videobot_listings l ON l.listing_id=r.listing_id ORDER BY l.created_at DESC,r.revision DESC LIMIT 20`);
 await q('RECENT_REGISTRATION_EVENTS',`SELECT left(md5(j.owner_id::text),10) AS owner_ref,j.status,j.created_at,j.updated_at,split_part(j.payload->'callback_query'->>'data','|',1) AS action,w.status AS receipt_status FROM videobot_owner_update_jobs j LEFT JOIN videobot_webhook_updates w USING(update_id) WHERE j.payload->'callback_query'->>'data' ~ '^(review:|entry:register|menu:listing)' ORDER BY j.update_id DESC LIMIT 25`);
 await c.query('ROLLBACK');
}finally{c.release();await p.end()}
JS

# Report only connectivity and content markers from the existing canonical terms URL.
url=https://tgtumbler-docs.pages.dev/createvdobot-terms.html
tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT
if curl -fsSL --connect-timeout 5 --max-time 15 "$url" -o "$tmp";then
 printf 'TERMS_BODY_BYTES=';wc -c < "$tmp"
 grep -qi 'CreateVdobot' "$tmp" && echo TERMS_NAME_PRESENT || true
 grep -q '規約' "$tmp" && echo TERMS_BODY_PRESENT || true
else echo TERMS_HTTP_UNAVAILABLE;fi
